create table if not exists public.users (
  id text primary key,
  username text,
  display_name text,
  role text,
  password_hash text,
  active boolean default true,
  is_demo boolean default false,
  created_at timestamptz default now(),
  last_login timestamptz,
  unique (username)
);
alter table public.users enable row level security;

create table if not exists public.sessions (
  token_hash text primary key,
  user_id text,
  created_at timestamptz default now(),
  expires_at timestamptz
);
alter table public.sessions enable row level security;

create table if not exists public.mission_progress (
  user_id text,
  mission_id text,
  stage_id text,
  status text,
  score integer,
  step_results jsonb default '{}'::jsonb,
  started_at timestamptz,
  completed_at timestamptz,
  last_activity timestamptz,
  primary key (user_id, mission_id)
);
alter table public.mission_progress enable row level security;

create table if not exists public.attempts (
  id text primary key,
  user_id text,
  mission_id text,
  step_id text,
  stage_id text,
  answer text,
  correct boolean,
  score integer,
  created_at timestamptz default now()
);
alter table public.attempts enable row level security;

create table if not exists public.certificates (
  id text primary key,
  user_id text,
  cert_key text,
  title text,
  reason text,
  serial text,
  issued_at timestamptz,
  revoked boolean default false,
  unique (user_id, cert_key)
);
alter table public.certificates enable row level security;

create table if not exists public.resources (
  id text primary key,
  stage_id text,
  kind text,
  title text,
  url text,
  description text,
  source text,
  visible boolean default true,
  sort integer,
  created_at timestamptz default now()
);
alter table public.resources enable row level security;

create table if not exists public.custom_missions (
  id text primary key,
  stage_id text,
  title text,
  summary text,
  steps jsonb default '[]'::jsonb,
  active boolean default true,
  created_at timestamptz default now()
);
alter table public.custom_missions enable row level security;

create table if not exists public.mission_overrides (
  mission_id text primary key,
  active boolean default true
);
alter table public.mission_overrides enable row level security;

create table if not exists public.forum_posts (
  id text primary key,
  user_id text,
  parent_id text,
  title text,
  body text,
  pinned boolean,
  closed boolean,
  accepted boolean,
  created_at timestamptz default now()
);
alter table public.forum_posts enable row level security;

create table if not exists public.forum_thanks (
  post_id text,
  user_id text,
  created_at timestamptz default now(),
  primary key (post_id, user_id)
);
alter table public.forum_thanks enable row level security;

create table if not exists public.settings (
  key text primary key,
  value text
);
alter table public.settings enable row level security;

create index if not exists ix_attempts_user on public.attempts (user_id, created_at);

-- Row Level Security is ON and no public policies are created.
-- That means the public 'anon' key can read or write NOTHING.
-- The app talks to the database only from the server with the SERVICE
-- key (keep it secret: .streamlit/secrets.toml or an environment variable;
-- never put it in a web page or a public repository).
